"""Explicit DX extension contracts, published before the corresponding RTL."""
import copy
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]


def save(name,module):
    (ROOT/f'spec/{name}_contract.json').write_text(json.dumps({'modules':[module]},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')


def main():
    m=copy.deepcopy(json.loads((ROOT/'spec/AxisEnvelopeMulti_contract.json').read_text(encoding='utf-8'))['modules'][0])
    m.update(name='AxisDxEnvelope',rtl_path='rtl/AxisDxEnvelope.v',description='DX 对数包络、键位/力度/速率缩放；独立任务与状态')
    for p in m['interfaces']['ports']:
        if p['name']=='i_s_axis_tdata': p['width']=384
        if p['name']=='o_m_axis_tdata': p['width']=96
    m['behavior']=[
        'Input words0..9: log-Q24 level, stage/event/restart, four scaled levels0..4032 (L4=0), four rates0..63.',
        'Word10: note[6:0], velocity[13:7], scaled output level[20:14]. Word11: breakpoint[6:0], LD[13:7], RD[20:14], LC[22:21], RC[24:23], KRS[27:25], KVS[30:28].',
        'Independent Python formulas in model/dx7_model.py; MSFA-derived key/velocity/rate tables. Increments rescaled from44100 to48828.125Hz.',
        'Output words: log-Q24 state, stage/status, normalized Q26 linear amplitude. Stages0=off,1..3=segments,4=hold,5=release. Events0=step,1=on,2=off,3=kill.',
        'E0 request; E1 stage/scaling decode; E2 key delta and rate; E3 target; E4 advance/exp2 read; E5 result valid. Single outstanding; result/tag stable under stall.',
        'Rate0 advances slowly; output becomes zero at the release floor. Each request advances at most one segment. Reset cancels pending result.',
        'Not bit-exact DX7: per-sample EG with256-entry exp2 LUT, normalized by8; no nonzero release-level profile.'
    ]
    m['constraints']=['Single50MHz clock; upstream validates parameter ranges. Level input0..(17<<24), note/velocity0..127, output0..127.','ROM contents generated by dx7_model.py must be present under rom/.','No extra operator latency permitted; hardware routing50MHz remains unverified.']
    m['verification_cases']=['Independent numerical vectors including all events, all curves, velocity/rate extremes, low levels and release.', 'Backpressure data/tag stability and reset cancellation.', 'Four factory presets and native operator regression.']
    m['timing_diagrams']=[dict(id='dx-step',title='DX 单次包络计算',scenario='stream',description='E0接收，E5结果有效；随后示例停顿两拍。',wavejson={'signal':[{'name':'clk','wave':'p.........'},{'name':'s_valid','wave':'10........'},{'name':'s_ready','wave':'10......1.'},{'name':'m_valid','wave':'0....1..0.'},{'name':'m_ready','wave':'0......1..'},{'name':'result/tag','wave':'x....=..x.','data':['stable result']} ]})]
    save('AxisDxEnvelope',m)
    additions={
        'AxisFmOperator':['DX extension: request flags word19 bit5 selects DX mode; bits12:6 note,19:13 velocity,26:20 scaled output level. Word20 carries packed key/velocity scaling.', 'DX envelope executes in parallel with wave math. State result is logarithmic, amplitude is separate. PM source normalized by8 restores phase with source<<9; feedback strength0..7 uses history_average<<(strength+1). DX sine reads old phase before increment.'],
        'VoiceSynthEngine':['DX extension: A1 flags15 mode,22:16 scaled output; DX sine/PM only, feedback0..7, depth0, ratio<=64. A2 DX levels<=4032,L4=0,rates<=63; A1 invalidates that row EG until A2 reloads it.', 'A4/A6 optional word4 marker31 plus velocity[13:7]/note[6:0]. Zero defaults60/100. Duplicate identity must match metadata. Metadata stored independently per voice. Four resident slots and eight voices unchanged.', 'A3 returns BUSY10 when any active voice uses the slot and any row changes native/DX state format; the old bank stays live and the draft remains available for a later new-sequence retry after voices finish or panic.'],
        'AxiVoiceEndpoint':['DX ABI0x00010005 exposes the extended A1/A2 and A4/A6 encodings; old commands remain valid.']}
    for name,lines in additions.items():
        path=ROOT/f'spec/{name}_contract.json';m=json.loads(path.read_text(encoding='utf-8'))['modules'][0]
        m['behavior']=[x for x in m['behavior'] if not x.startswith('DX extension:') and not x.startswith('DX ABI')]
        for line in lines:
            if line not in m['behavior']:m['behavior'].append(line)
        save(name,m)


if __name__=='__main__':main()
